import sys

def solve():
    s = sys.stdin.readline().strip()
    m = len(s)

    if m == 1:
        if s.isupper():
            s = s.lower()
        else:
            s = s.upper()
    elif all(c.isupper() for c in s):
        s = s.lower()
    elif s[0].islower() and all(c.isupper() for c in s[1:]):
        s = s[0].upper() + s[1:].lower()

    sys.stdout.write(s)

if __name__ == "__main__":
    solve()

